variants.indirect:
import Base

def apply(~f: Nat -> Nat, value: Nat) -> Nat:
  f(value)

@unsafe def walk(value: Nat) -> Nat:
  match value:
    case Zero{}: Zero{}
    case Succ{rest}: apply(~walk, rest)

variants.direct:
import Base

def apply(~f: Nat -> Nat, value: Nat) -> Nat:
  f(value)

@unsafe def walk(value: Nat) -> Nat:
  match value:
    case Zero{}: Zero{}
    case Succ{rest}: walk(rest)

variants.earlier-definition:
import Base

def apply(~f: Nat -> Nat, value: Nat) -> Nat:
  f(value)

def identity(value: Nat) -> Nat: value

@unsafe def walk(value: Nat) -> Nat:
  match value:
    case Zero{}: Zero{}
    case Succ{rest}: apply(~identity, rest)
